@users_bp.route("/<int:user_id>/export", methods=["GET"])
@require_auth
def export_user(user_id: int):
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    orders = session.query(Order).filter(Order.user_id == user_id).all()
    return jsonify({"user": user.to_dict(include_email=True), "orders": [o.to_dict() for o in orders]})

@users_bp.route("/<int:user_id>", methods=["GET"])
@require_auth
def get_user(user_id: int):
    if not is_owner_or_admin(g.current_user, user_id):
        return jsonify({"error": "forbidden"}), 403
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    return jsonify(user.to_dict(include_email=True))

def require_auth(fn):
    """Reject the request unless a valid user token is presented."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)
    return wrapper

def to_dict(self) -> dict:
    return {
        "id": self.id,
        "user_id": self.user_id,
        "status": self.status,
        "total": self.total,
        "shipping_address": self.shipping_address,
    }

